#!/usr/bin/env python3
"""Minimal pure-Python PDF toolkit (stdlib only): parsing, decoding, serialization."""

import re
import zlib


class PdfParseError(Exception):
    pass


class Ref:
    __slots__ = ("num", "gen")

    def __init__(self, num, gen=0):
        self.num = int(num)
        self.gen = int(gen)

    def __repr__(self):
        return f"Ref({self.num},{self.gen})"

    def __hash__(self):
        return hash((self.num, self.gen))

    def __eq__(self, other):
        return isinstance(other, Ref) and self.num == other.num and self.gen == other.gen


class StreamObj:
    __slots__ = ("dict", "raw")

    def __init__(self, d, raw):
        self.dict = d
        self.raw = raw


_WS = b"\x00\t\n\x0c\r "


def skip_ws(data, pos):
    n = len(data)
    while pos < n:
        ch = data[pos]
        if ch in _WS:
            pos += 1
        elif ch == 0x25:  # '%'
            while pos < n and data[pos] not in b"\r\n":
                pos += 1
        else:
            break
    return pos


def parse_number(data, pos):
    n = len(data)
    start = pos
    while pos < n and data[pos] in b"0123456789+-.":
        pos += 1
    tok = data[start:pos]
    if not tok:
        raise PdfParseError("empty number")
    if b"." in tok:
        return float(tok), pos
    return int(tok), pos


def parse_name(data, pos):
    pos += 1
    out = bytearray()
    n = len(data)
    while pos < n:
        ch = data[pos]
        if ch in _WS or ch in b"()<>[]{}/%":
            break
        if ch == 0x23 and pos + 2 < n:  # '#'
            try:
                out.append(int(data[pos + 1:pos + 3], 16))
                pos += 3
                continue
            except ValueError:
                pass
        out.append(ch)
        pos += 1
    return bytes(out), pos


def parse_literal_string(data, pos):
    pos += 1
    out = bytearray()
    depth = 1
    n = len(data)
    while pos < n:
        ch = data[pos]
        if ch == 0x5C:  # backslash
            nxt = data[pos + 1:pos + 2]
            if nxt == b"n":
                out.append(10); pos += 2
            elif nxt == b"r":
                out.append(13); pos += 2
            elif nxt == b"t":
                out.append(9); pos += 2
            elif nxt == b"b":
                out.append(8); pos += 2
            elif nxt == b"f":
                out.append(12); pos += 2
            elif nxt in b"()\\":
                out.append(nxt[0]); pos += 2
            elif nxt in b"01234567":
                j = pos + 1
                val = 0
                k = 0
                while k < 3 and j < n and data[j] in b"01234567":
                    val = val * 8 + (data[j] - 48)
                    j += 1
                    k += 1
                out.append(val & 0xFF)
                pos = j
            elif nxt == b"":
                pos += 1
            elif nxt in (b"\r", b"\n"):
                # line continuation
                if nxt == b"\r" and pos + 2 < n and data[pos + 2] == b"\n":
                    pos += 3
                else:
                    pos += 2
            else:
                out.append(nxt[0]); pos += 2
        elif ch == 0x28:  # (
            depth += 1
            out.append(ch); pos += 1
        elif ch == 0x29:  # )
            depth -= 1
            if depth == 0:
                return bytes(out), pos + 1
            out.append(ch); pos += 1
        else:
            out.append(ch); pos += 1
    raise PdfParseError("unterminated literal string")


def parse_hex_string(data, pos):
    pos += 1
    out = bytearray()
    n = len(data)
    while pos < n and data[pos] != 0x3E:
        ch = data[pos]
        if ch in _WS:
            pos += 1
            continue
        hi = int(chr(ch), 16)
        pos += 1
        if pos < n and data[pos] != 0x3E and data[pos] not in _WS:
            lo = int(chr(data[pos]), 16)
            pos += 1
        else:
            lo = 0
        out.append((hi << 4) | lo)
    if pos >= n:
        raise PdfParseError("unterminated hex string")
    return bytes(out), pos + 1


def parse_array(data, pos):
    pos += 1
    arr = []
    n = len(data)
    while True:
        pos = skip_ws(data, pos)
        if pos >= n:
            raise PdfParseError("unterminated array")
        if data[pos:pos + 1] == b"]":
            return arr, pos + 1
        val, pos = parse_object(data, pos)
        arr.append(val)


def parse_dict(data, pos):
    pos += 2
    d = {}
    n = len(data)
    while True:
        pos = skip_ws(data, pos)
        if pos >= n:
            raise PdfParseError("unterminated dictionary")
        if data[pos:pos + 2] == b">>":
            return d, pos + 2
        key, pos = parse_name(data, pos)
        pos = skip_ws(data, pos)
        val, pos = parse_object(data, pos)
        d[key] = val


def parse_object(data, pos):
    pos = skip_ws(data, pos)
    if pos >= len(data):
        raise PdfParseError("unexpected end of data")
    ch = data[pos]
    if ch == 0x3C:
        if data[pos:pos + 2] == b"<<":
            return parse_dict(data, pos)
        return parse_hex_string(data, pos)
    if ch == 0x5B:
        return parse_array(data, pos)
    if ch == 0x28:
        return parse_literal_string(data, pos)
    if ch == 0x2F:
        return parse_name(data, pos)
    if ch in b"0123456789+-.":
        num, pos2 = parse_number(data, pos)
        pos3 = skip_ws(data, pos2)
        if pos3 < len(data) and data[pos3] in b"0123456789":
            gen, pos4 = parse_number(data, pos3)
            pos5 = skip_ws(data, pos4)
            if pos5 < len(data) and data[pos5] == 0x52:  # 'R'
                if isinstance(num, int) and isinstance(gen, int):
                    return Ref(num, gen), pos5 + 1
        return num, pos2
    if data.startswith(b"true", pos):
        return True, pos + 4
    if data.startswith(b"false", pos):
        return False, pos + 5
    if data.startswith(b"null", pos):
        return None, pos + 4
    raise PdfParseError(f"cannot parse object at offset {pos}: {data[pos:pos + 24]!r}")


def read_object_at_offset(data, offset):
    pos = skip_ws(data, offset)
    num, pos = parse_number(data, pos)
    pos = skip_ws(data, pos)
    gen, pos = parse_number(data, pos)
    pos = skip_ws(data, pos)
    if data[pos:pos + 3] != b"obj":
        raise PdfParseError(f"expected 'obj' at offset {offset}")
    pos += 3
    obj, pos = parse_object(data, pos)
    stream = None
    pos2 = skip_ws(data, pos)
    if data[pos2:pos2 + 6] == b"stream":
        p = pos2 + 6
        if data[p:p + 2] == b"\r\n":
            p += 2
        elif data[p:p + 1] in (b"\n", b"\r"):
            p += 1
        length = None
        if isinstance(obj, dict) and isinstance(obj.get(b"Length"), int):
            length = obj[b"Length"]
        if length is not None and p + length <= len(data):
            stream = data[p:p + length]
        else:
            e = data.find(b"endstream", p)
            if e == -1:
                raise PdfParseError("endstream not found")
            stream = data[p:e]
    return num, gen, obj, stream


def flate_decode(data):
    try:
        return zlib.decompress(data)
    except zlib.error:
        d = zlib.decompressobj(-15)
        return d.decompress(data) + d.flush()


def ascii85_decode(data):
    out = bytearray()
    buf = []
    for ch in data:
        if ch in b" \t\r\n\0":
            continue
        if ch == 0x7E:  # '~'
            break
        if ch == 0x7A and not buf:  # 'z'
            out += b"\x00\x00\x00\x00"
            continue
        if 0x21 <= ch <= 0x75:
            buf.append(ch - 33)
            if len(buf) == 5:
                val = 0
                for b in buf:
                    val = val * 85 + b
                out += val.to_bytes(4, "big")
                buf = []
        else:
            raise PdfParseError("bad ascii85 char")
    if buf:
        pad = 5 - len(buf)
        buf += [84] * pad
        val = 0
        for b in buf:
            val = val * 85 + b
        raw = val.to_bytes(4, "big")
        out += raw[:5 - pad]
    return bytes(out)


def ascii_hex_decode(data):
    out = bytearray()
    digits = bytearray()
    for ch in data:
        if ch in b" \t\r\n\0":
            continue
        if ch == 0x3E:
            break
        digits.append(ch)
    if len(digits) % 2:
        digits.append(0x30)
    for i in range(0, len(digits), 2):
        out.append((int(chr(digits[i]), 16) << 4) | int(chr(digits[i + 1]), 16))
    return bytes(out)


def apply_predictor(data, parms):
    if not isinstance(parms, dict):
        return data
    predictor = parms.get(b"Predictor", 1)
    if not isinstance(predictor, int) or predictor <= 1:
        return data
    colors = parms.get(b"Colors", 1)
    bpc = parms.get(b"BitsPerComponent", 8)
    columns = parms.get(b"Columns", 1)
    if not all(isinstance(x, int) for x in (colors, bpc, columns)):
        return data
    if bpc != 8:
        raise PdfParseError(f"unsupported predictor bpc {bpc}")
    bpp = max(1, (colors * bpc + 7) // 8)
    rowlen = (colors * bpc * columns + 7) // 8
    if predictor == 2:  # TIFF
        out = bytearray()
        for off in range(0, len(data), rowlen):
            row = bytearray(data[off:off + rowlen])
            for i in range(bpp, rowlen):
                row[i] = (row[i] + row[i - bpp]) & 0xFF
            out += row
        return bytes(out)
    if 10 <= predictor <= 15:  # PNG
        out = bytearray()
        prev = bytearray(rowlen)
        pos = 0
        while pos < len(data):
            ft = data[pos]
            pos += 1
            row = bytearray(data[pos:pos + rowlen])
            pos += rowlen
            if ft == 1:
                for i in range(bpp, rowlen):
                    row[i] = (row[i] + row[i - bpp]) & 0xFF
            elif ft == 2:
                for i in range(rowlen):
                    row[i] = (row[i] + prev[i]) & 0xFF
            elif ft == 3:
                for i in range(rowlen):
                    left = row[i - bpp] if i >= bpp else 0
                    row[i] = (row[i] + ((left + prev[i]) >> 1)) & 0xFF
            elif ft == 4:
                for i in range(rowlen):
                    left = row[i - bpp] if i >= bpp else 0
                    up = prev[i]
                    ul = prev[i - bpp] if i >= bpp else 0
                    p = left + up - ul
                    pa = abs(p - left); pb = abs(p - up); pc = abs(p - ul)
                    if pa <= pb and pa <= pc:
                        pr = left
                    elif pb <= pc:
                        pr = up
                    else:
                        pr = ul
                    row[i] = (row[i] + pr) & 0xFF
            elif ft != 0:
                raise PdfParseError(f"unknown PNG predictor {ft}")
            out += row
            prev = row
        return bytes(out)
    raise PdfParseError(f"unsupported predictor {predictor}")


def decode_stream(d, raw):
    filt = d.get(b"Filter")
    if filt is None:
        return raw
    if isinstance(filt, bytes):
        filters = [filt]
    else:
        filters = list(filt)
    parms = d.get(b"DecodeParms")
    data = raw
    for i, f in enumerate(filters):
        if not isinstance(f, bytes):
            raise PdfParseError(f"bad filter entry {f!r}")
        if f == b"FlateDecode":
            data = flate_decode(data)
            p = parms[i] if isinstance(parms, list) else parms
            data = apply_predictor(data, p)
        elif f == b"ASCIIHexDecode":
            data = ascii_hex_decode(data)
        elif f == b"ASCII85Decode":
            data = ascii85_decode(data)
        else:
            raise PdfParseError(f"unsupported stream filter {f!r}")
    return data


def parse_classic_xref(data, offset):
    pos = skip_ws(data, offset)
    if data[pos:pos + 4] != b"xref":
        raise PdfParseError("expected 'xref'")
    pos = skip_ws(data, pos + 4)
    entries = {}
    while True:
        m = re.match(rb"(\d+)\s+(\d+)", data[pos:pos + 64])
        if not m:
            break
        start = int(m.group(1))
        count = int(m.group(2))
        pos += m.end()
        for _ in range(count):
            mm = re.match(rb"(\d{10}) (\d{5}) ([nf])[ \t]*(?:\r\n|\r|\n)",
                          data[pos:pos + 24])
            if not mm:
                raise PdfParseError(f"bad xref entry near offset {pos}")
            off = int(mm.group(1))
            gen = int(mm.group(2))
            typ = mm.group(3)
            entries[start] = (0, off, gen) if typ == b"f" else (1, off, gen)
            start += 1
            pos += mm.end()
        pos = skip_ws(data, pos)
    if data[pos:pos + 7] != b"trailer":
        raise PdfParseError("expected 'trailer'")
    trailer, _ = parse_dict(data, pos + 7)
    return entries, trailer


def decode_xref_stream(d, raw):
    dec = decode_stream(d, raw)
    w = d.get(b"W")
    if not isinstance(w, list) or len(w) != 3:
        raise PdfParseError("bad /W in xref stream")
    w1, w2, w3 = int(w[0]), int(w[1]), int(w[2])
    idx = d.get(b"Index")
    if idx is None:
        size = int(d.get(b"Size", 0))
        pairs = [(0, size)]
    else:
        pairs = [(int(idx[i]), int(idx[i + 1])) for i in range(0, len(idx), 2)]
    width = w1 + w2 + w3

    def read_int(off, wd):
        val = 0
        for k in range(wd):
            val = (val << 8) | dec[off + k]
        return val

    out = {}
    pos = 0
    for start, count in pairs:
        for i in range(count):
            if pos + width > len(dec):
                raise PdfParseError("xref stream data too short")
            t = read_int(pos, w1) if w1 else 1
            f2 = read_int(pos + w1, w2) if w2 else 0
            f3 = read_int(pos + w1 + w2, w3) if w3 else 0
            pos += width
            if t == 1 and w2 == 0:
                f2 = start + i
            if t == 0:
                out[start + i] = (0, f2, f3)
            elif t == 1:
                out[start + i] = (1, f2, f3)
            elif t == 2:
                out[start + i] = (2, f2, f3)
            else:
                raise PdfParseError(f"bad xref entry type {t}")
    return out


def parse_pdf(data):
    m = list(re.finditer(rb"startxref", data))
    if not m:
        raise PdfParseError("no startxref found")
    offset = None
    for mm in reversed(m):
        pos = skip_ws(data, mm.end())
        mnum = re.match(rb"\d+", data[pos:pos + 32])
        if mnum:
            offset = int(mnum.group(0))
            break
    if offset is None:
        raise PdfParseError("bad startxref")
    sections = []
    trailer = None
    seen = set()
    while offset is not None and offset not in seen and 0 <= offset < len(data):
        seen.add(offset)
        pos = skip_ws(data, offset)
        if data[pos:pos + 4] == b"xref":
            entries, t = parse_classic_xref(data, offset)
            sections.append(entries)
            if trailer is None:
                trailer = t
            xrefstm = t.get(b"XRefStm")
            if isinstance(xrefstm, int):
                try:
                    e2, _ = parse_classic_xref(data, xrefstm)
                    sections.append(e2)
                except PdfParseError:
                    pass
            offset = t.get(b"Prev")
        else:
            onum, ogen, obj, stream = read_object_at_offset(data, offset)
            if not isinstance(obj, dict) or obj.get(b"Type") != b"XRef" or stream is None:
                raise PdfParseError(f"expected xref stream at offset {offset}")
            entries = decode_xref_stream(obj, stream)
            sections.append(entries)
            if trailer is None:
                trailer = obj
            offset = obj.get(b"Prev")
        if offset is not None:
            offset = int(offset)
    if trailer is None:
        raise PdfParseError("no trailer found")
    entries = {}
    for sec in reversed(sections):
        for num, val in sec.items():
            if num not in entries:
                entries[num] = val
    return entries, trailer


def extract_objstm(stm):
    if not isinstance(stm, StreamObj):
        return {}
    d = stm.dict
    if d.get(b"Type") != b"ObjStm":
        return {}
    try:
        dec = decode_stream(d, stm.raw)
    except PdfParseError:
        return {}
    n = d.get(b"N")
    first = d.get(b"First")
    if not isinstance(n, int) or not isinstance(first, int):
        return {}
    toks = []
    pos = 0
    for _ in range(n * 2):
        pos = skip_ws(dec, pos)
        num, pos = parse_number(dec, pos)
        toks.append(int(num))
    out = {}
    for i in range(n):
        objnum = toks[2 * i]
        off = toks[2 * i + 1]
        try:
            val, _ = parse_object(dec, first + off)
        except PdfParseError:
            val = None
        out[objnum] = val
    return out


def load_objects(data, entries):
    objects = {}
    for num, (typ, f2, f3) in entries.items():
        if typ == 1:
            try:
                onum, ogen, obj, stream = read_object_at_offset(data, f2)
                if stream is not None:
                    objects[num] = (f3, StreamObj(obj, stream))
                else:
                    objects[num] = (f3, obj)
            except PdfParseError:
                objects[num] = (f3, None)
    cache = {}
    for num, (typ, f2, f3) in entries.items():
        if typ == 2:
            stm = objects.get(f2)
            if stm is None:
                continue
            if f2 not in cache:
                cache[f2] = extract_objstm(stm)
            embedded = cache[f2]
            if num in embedded:
                objects[num] = (0, embedded[num])
    return objects


def load_pdf(data):
    entries, trailer = parse_pdf(data)
    objects = load_objects(data, entries)
    return entries, trailer, objects


def serialize_string(s):
    out = bytearray(b"(")
    for ch in s:
        if ch in (0x28, 0x29, 0x5C):  # ( ) \
            out += b"\\" + bytes([ch])
        elif 32 <= ch <= 126:
            out.append(ch)
        elif ch == 8:
            out += b"\\b"
        elif ch == 9:
            out += b"\\t"
        elif ch == 10:
            out += b"\\n"
        elif ch == 12:
            out += b"\\f"
        elif ch == 13:
            out += b"\\r"
        else:
            out += b"\\%03o" % ch
    out.append(0x29)
    return bytes(out)


def serialize_value(v):
    if isinstance(v, Ref):
        return b"%d %d R" % (v.num, v.gen)
    if isinstance(v, bool):
        return b"true" if v else b"false"
    if v is None:
        return b"null"
    if isinstance(v, int):
        return b"%d" % v
    if isinstance(v, float):
        return b"%r" % v
    if isinstance(v, bytes):
        return serialize_string(v)
    if isinstance(v, list):
        return b"[" + b" ".join(serialize_value(x) for x in v) + b"]"
    if isinstance(v, dict):
        parts = []
        for k in sorted(v.keys()):
            parts.append(b"/" + k + b" " + serialize_value(v[k]))
        return b"<< " + b" ".join(parts) + b" >>"
    raise PdfParseError(f"cannot serialize {type(v)}")


class PdfBuilder:
    def __init__(self, source_objects):
        self.source_objects = source_objects
        self.objects = {}       # new object number -> structure (or None placeholder)
        self.obj_map = {}       # (old_num, old_gen) -> new number
        self.next_num = 1

    def register(self, structure):
        num = self.next_num
        self.next_num += 1
        self.objects[num] = structure
        return Ref(num, 0)

    def copy_value(self, v):
        if isinstance(v, Ref):
            return self.copy_object(v)
        if isinstance(v, dict):
            return {k: self.copy_value(x) for k, x in v.items()}
        if isinstance(v, list):
            return [self.copy_value(x) for x in v]
        if isinstance(v, StreamObj):
            d = {k: self.copy_value(x) for k, x in v.dict.items()}
            return StreamObj(d, v.raw)
        return v

    def copy_object(self, ref):
        key = (ref.num, ref.gen)
        if key in self.obj_map:
            return Ref(self.obj_map[key], 0)
        src = self.source_objects.get(ref.num)
        if src is None or src[1] is None:
            raise PdfParseError(f"missing object {ref.num}")
        num = self.next_num
        self.next_num += 1
        self.obj_map[key] = num
        copied = self.copy_value(src[1])
        self.objects[num] = copied
        return Ref(num, 0)


# Helvetica glyph widths (units per 1000), ASCII 32..126
HELVETICA_WIDTHS = [
    278, 278, 355, 556, 556, 889, 667, 191, 333, 333, 389, 584, 278, 333, 278, 278,
    556, 556, 556, 556, 556, 556, 556, 556, 556, 556, 278, 278, 584, 584, 584, 556,
    1015, 667, 667, 722, 722, 667, 611, 778, 722, 278, 500, 667, 556, 833, 722, 778,
    667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611, 278, 278, 278, 469, 556,
    333, 556, 556, 500, 556, 556, 278, 556, 556, 222, 222, 500, 222, 833, 556, 556,
    556, 556, 333, 500, 278, 556, 500, 722, 500, 500, 500, 334, 260, 334, 584,
]


def text_width(s, size):
    w = 0
    for ch in s:
        o = ord(ch)
        w += HELVETICA_WIDTHS[o - 32] if 32 <= o <= 126 else 556
    return w * size / 1000.0


def extract_simple_text(data):
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        while i < n and data[i] in b" \t\r\n\f\0":
            i += 1
        if i >= n:
            break
        ch = data[i]
        if data[i:i + 2] == b"BI":  # inline image begin
            j = data.find(b"ID", i + 2)
            if j == -1:
                break
            k = j + 2
            while k < n and data[k] in b" \t\r\n\f\0":
                k += 1
            e = data.find(b"EI", k)
            if e == -1:
                break
            i = e + 2
            continue
        if ch == 0x28:
            s, i2 = parse_literal_string(data, i)
            out += s + b" "
            i = i2
            continue
        if data[i:i + 2] == b"<<":
            i += 2
            continue
        if ch == 0x3C:
            try:
                s, i2 = parse_hex_string(data, i)
            except PdfParseError:
                i += 1
                continue
            out += s + b" "
            i = i2
            continue
        if ch == 0x5B:
            try:
                arr, i2 = parse_array(data, i)
            except PdfParseError:
                i += 1
                continue
            for item in arr:
                if isinstance(item, bytes):
                    out += item + b" "
            i = i2
            continue
        i += 1
    return bytes(out)


def extract_text_from_page(page, objects):
    streams = []

    def add(v):
        if isinstance(v, Ref):
            obj = objects.get(v.num)
            if obj and isinstance(obj[1], StreamObj):
                streams.append(obj[1])
        elif isinstance(v, list):
            for x in v:
                add(x)

    add(page.get(b"Contents"))
    parts = []
    for s in streams:
        try:
            dec = decode_stream(s.dict, s.raw)
        except PdfParseError:
            continue
        parts.append(extract_simple_text(dec))
    return b"\n".join(parts)


if __name__ == "__main__":
    import sys
    from collections import Counter

    path = sys.argv[1] if len(sys.argv) > 1 else "report.pdf"
    try:
        data = open(path, "rb").read()
    except OSError as exc:
        print("error:", exc)
        sys.exit(1)
    print(f"File: {path}  ({len(data)} bytes)")
    m = re.match(rb"%PDF-(\d+\.\d+)", data[:16])
    print("PDF version:", m.group(1).decode() if m else "unknown")
    try:
        entries, trailer, objects = load_pdf(data)
    except PdfParseError as exc:
        print("PARSE FAILED:", exc)
        sys.exit(1)
    print("Xref entries:", len(entries))
    print("Encrypted:", b"Encrypt" in trailer)
    root_ref = trailer.get(b"Root")
    print("Root:", root_ref)
    count = 0
    if isinstance(root_ref, Ref):
        root = objects.get(root_ref.num)
        if root and isinstance(root[1], dict):
            pages_ref = root[1].get(b"Pages")

            def walk(node_ref):
                global count
                node = objects.get(node_ref.num)
                if not node or not isinstance(node[1], dict):
                    return
                d = node[1]
                if d.get(b"Type") == b"Page":
                    count += 1
                elif d.get(b"Kids") is not None:
                    for kid in d[b"Kids"]:
                        if isinstance(kid, Ref):
                            walk(kid)

            if isinstance(pages_ref, Ref):
                walk(pages_ref)
    print("Pages:", count)
    types = Counter()
    filters = Counter()
    streams = 0
    for num, (gen, val) in objects.items():
        if isinstance(val, StreamObj):
            streams += 1
            f = val.dict.get(b"Filter")
            if isinstance(f, bytes):
                filters[f.decode()] += 1
            elif isinstance(f, list):
                for x in f:
                    if isinstance(x, bytes):
                        filters[x.decode()] += 1
            t = val.dict.get(b"Type")
            if isinstance(t, bytes):
                types[t.decode()] += 1
        elif isinstance(val, dict):
            t = val.get(b"Type")
            if isinstance(t, bytes):
                types[t.decode()] += 1
    print("Stream objects:", streams)
    print("Filters:", dict(filters))
    print("Types:", dict(types))

#!/usr/bin/env python3
"""Minimal pure-Python PDF toolkit (stdlib only): parsing, decoding, serialization."""

import re
import zlib


class PdfParseError(Exception):
    pass


class Ref:
    __slots__ = ("num", "gen")

    def __init__(self, num, gen=0):
        self.num = int(num)
        self.gen = int(gen)

    def __repr__(self):
        return f"Ref({self.num},{self.gen})"

    def __hash__(self):
        return hash((self.num, self.gen))

    def __eq__(self, other):
        return isinstance(other, Ref) and self.num == other.num and self.gen == other.gen


class StreamObj:
    __slots__ = ("dict", "raw")

    def __init__(self, d, raw):
        self.dict = d
        self.raw = raw


_WS = b"\x00\t\n\x0c\r "


def skip_ws(data, pos):
    n = len(data)
    while pos < n:
        ch = data[pos]
        if ch in _WS:
            pos += 1
        elif ch == 0x25:  # '%'
            while pos < n and data[pos] not in b"\r\n":
                pos += 1
        else:
            break
    return pos


def parse_number(data, pos):
    n = len(data)
    start = pos
    while pos < n and data[pos] in b"0123456789+-.":
        pos += 1
    tok = data[start:pos]
    if not tok:
        raise PdfParseError("empty number")
    if b"." in tok:
        return float(tok), pos
    return int(tok), pos


def parse_name(data, pos):
    pos += 1
    out = bytearray()
    n = len(data)
    while pos < n:
        ch = data[pos]
        if ch in _WS or ch in b"()<>[]{}/%":
            break
        if ch == 0x23 and pos + 2 < n:  # '#'
            try:
                out.append(int(data[pos + 1:pos + 3], 16))
                pos += 3
                continue
            except ValueError:
                pass
        out.append(ch)
        pos += 1
    return bytes(out), pos


def parse_literal_string(data, pos):
    pos += 1
    out = bytearray()
    depth = 1
    n = len(data)
    while pos < n:
        ch = data[pos]
        if ch == 0x5C:  # backslash
            nxt = data[pos + 1:pos + 2]
            if nxt == b"n":
                out.append(10); pos += 2
            elif nxt == b"r":
                out.append(13); pos += 2
            elif nxt == b"t":
                out.append(9); pos += 2
            elif nxt == b"b":
                out.append(8); pos += 2
            elif nxt == b"f":
                out.append(12); pos += 2
            elif nxt in b"()\\":
                out.append(nxt[0]); pos += 2
            elif nxt in b"01234567":
                j = pos + 1
                val = 0
                k = 0
                while k < 3 and j < n and data[j] in b"01234567":
                    val = val * 8 + (data[j] - 48)
                    j += 1
                    k += 1
                out.append(val & 0xFF)
                pos = j
            elif nxt == b"":
                pos += 1
            elif nxt in (b"\r", b"\n"):
                # line continuation
                if nxt == b"\r" and pos + 2 < n and data[pos + 2] == b"\n":
                    pos += 3
                else:
                    pos += 2
            else:
                out.append(nxt[0]); pos += 2
        elif ch == 0x28:  # (
            depth += 1
            out.append(ch); pos += 1
        elif ch == 0x29:  # )
            depth -= 1
            if depth == 0:
                return bytes(out), pos + 1
            out.append(ch); pos += 1
        else:
            out.append(ch); pos += 1
    raise PdfParseError("unterminated literal string")


def parse_hex_string(data, pos):
    pos += 1
    out = bytearray()
    n = len(data)
    while pos < n and data[pos] != 0x3E:
        ch = data[pos]
        if ch in _WS:
            pos += 1
            continue
        hi = int(chr(ch), 16)
        pos += 1
        if pos < n and data[pos] != 0x3E and data[pos] not in _WS:
            lo = int(chr(data[pos]), 16)
            pos += 1
        else:
            lo = 0
        out.append((hi << 4) | lo)
    if pos >= n:
        raise PdfParseError("unterminated hex string")
    return bytes(out), pos + 1


def parse_array(data, pos):
    pos += 1
    arr = []
    n = len(data)
    while True:
        pos = skip_ws(data, pos)
        if pos >= n:
            raise PdfParseError("unterminated array")
        if data[pos:pos + 1] == b"]":
            return arr, pos + 1
        val, pos = parse_object(data, pos)
        arr.append(val)


def parse_dict(data, pos):
    pos += 2
    d = {}
    n = len(data)
    while True:
        pos = skip_ws(data, pos)
        if pos >= n:
            raise PdfParseError("unterminated dictionary")
        if data[pos:pos + 2] == b">>":
            return d, pos + 2
        key, pos = parse_name(data, pos)
        pos = skip_ws(data, pos)
        val, pos = parse_object(data, pos)
        d[key] = val


def parse_object(data, pos):
    pos = skip_ws(data, pos)
    if pos >= len(data):
        raise PdfParseError("unexpected end of data")
    ch = data[pos]
    if ch == 0x3C:
        if data[pos:pos + 2] == b"<<":
            return parse_dict(data, pos)
        return parse_hex_string(data, pos)
    if ch == 0x5B:
        return parse_array(data, pos)
    if ch == 0x28:
        return parse_literal_string(data, pos)
    if ch == 0x2F:
        return parse_name(data, pos)
    if ch in b"0123456789+-.":
        num, pos2 = parse_number(data, pos)
        pos3 = skip_ws(data, pos2)
        if pos3 < len(data) and data[pos3] in b"0123456789":
            gen, pos4 = parse_number(data, pos3)
            pos5 = skip_ws(data, pos4)
            if pos5 < len(data) and data[pos5] == 0x52:  # 'R'
                if isinstance(num, int) and isinstance(gen, int):
                    return Ref(num, gen), pos5 + 1
        return num, pos2
    if data.startswith(b"true", pos):
        return True, pos + 4
    if data.startswith(b"false", pos):
        return False, pos + 5
    if data.startswith(b"null", pos):
        return None, pos + 4
    raise PdfParseError(f"cannot parse object at offset {pos}: {data[pos:pos + 24]!r}")


def read_object_at_offset(data, offset):
    pos = skip_ws(data, offset)
    num, pos = parse_number(data, pos)
    pos = skip_ws(data, pos)
    gen, pos = parse_number(data, pos)
    pos = skip_ws(data, pos)
    if data[pos:pos + 3] != b"obj":
        raise PdfParseError(f"expected 'obj' at offset {offset}")
    pos += 3
    obj, pos = parse_object(data, pos)
    stream = None
    pos2 = skip_ws(data, pos)
    if data[pos2:pos2 + 6] == b"stream":
        p = pos2 + 6
        if data[p:p + 2] == b"\r\n":
            p += 2
        elif data[p:p + 1] in (b"\n", b"\r"):
            p += 1
        length = None
        if isinstance(obj, dict) and isinstance(obj.get(b"Length"), int):
            length = obj[b"Length"]
        if length is not None and p + length <= len(data):
            stream = data[p:p + length]
        else:
            e = data.find(b"endstream", p)
            if e == -1:
                raise PdfParseError("endstream not found")
            stream = data[p:e]
    return num, gen, obj, stream


def flate_decode(data):
    try:
        return zlib.decompress(data)
    except zlib.error:
        d = zlib.decompressobj(-15)
        return d.decompress(data) + d.flush()


def ascii85_decode(data):
    out = bytearray()
    buf = []
    for ch in data:
        if ch in b" \t\r\n\0":
            continue
        if ch == 0x7E:  # '~'
            break
        if ch == 0x7A and not buf:  # 'z'
            out += b"\x00\x00\x00\x00"
            continue
        if 0x21 <= ch <= 0x75:
            buf.append(ch - 33)
            if len(buf) == 5:
                val = 0
                for b in buf:
                    val = val * 85 + b
                out += val.to_bytes(4, "big")
                buf = []
        else:
            raise PdfParseError("bad ascii85 char")
    if buf:
        pad = 5 - len(buf)
        buf += [84] * pad
        val = 0
        for b in buf:
            val = val * 85 + b
        raw = val.to_bytes(4, "big")
        out += raw[:5 - pad]
    return bytes(out)


def ascii_hex_decode(data):
    out = bytearray()
    digits = bytearray()
    for ch in data:
        if ch in b" \t\r\n\0":
            continue
        if ch == 0x3E:
            break
        digits.append(ch)
    if len(digits) % 2:
        digits.append(0x30)
    for i in range(0, len(digits), 2):
        out.append((int(chr(digits[i]), 16) << 4) | int(chr(digits[i + 1]), 16))
    return bytes(out)


def apply_predictor(data, parms):
    if not isinstance(parms, dict):
        return data
    predictor = parms.get(b"Predictor", 1)
    if not isinstance(predictor, int) or predictor <= 1:
        return data
    colors = parms.get(b"Colors", 1)
    bpc = parms.get(b"BitsPerComponent", 8)
    columns = parms.get(b"Columns", 1)
    if not all(isinstance(x, int) for x in (colors, bpc, columns)):
        return data
    if bpc != 8:
        raise PdfParseError(f"unsupported predictor bpc {bpc}")
    bpp = max(1, (colors * bpc + 7) // 8)
    rowlen = (colors * bpc * columns + 7) // 8
    if predictor == 2:  # TIFF
        out = bytearray()
        for off in range(0, len(data), rowlen):
            row = bytearray(data[off:off + rowlen])
            for i in range(bpp, rowlen):
                row[i] = (row[i] + row[i - bpp]) & 0xFF
            out += row
        return bytes(out)
    if 10 <= predictor <= 15:  # PNG
        out = bytearray()
        prev = bytearray(rowlen)
        pos = 0
        while pos < len(data):
            ft = data[pos]
            pos += 1
            row = bytearray(data[pos:pos + rowlen])
            pos += rowlen
            if ft == 1:
                for i in range(bpp, rowlen):
                    row[i] = (row[i] + row[i - bpp]) & 0xFF
            elif ft == 2:
                for i in range(rowlen):
                    row[i] = (row[i] + prev[i]) & 0xFF
            elif ft == 3:
                for i in range(rowlen):
                    left = row[i - bpp] if i >= bpp else 0
                    row[i] = (row[i] + ((left + prev[i]) >> 1)) & 0xFF
            elif ft == 4:
                for i in range(rowlen):
                    left = row[i - bpp] if i >= bpp else 0
                    up = prev[i]
                    ul = prev[i - bpp] if i >= bpp else 0
                    p = left + up - ul
                    pa = abs(p - left); pb = abs(p - up); pc = abs(p - ul)
                    if pa <= pb and pa <= pc:
                        pr = left
                    elif pb <= pc:
                        pr = up
                    else:
                        pr = ul
                    row[i] = (row[i] + pr) & 0xFF
            elif ft != 0:
                raise PdfParseError(f"unknown PNG predictor {ft}")
            out += row
            prev = row
        return bytes(out)
    raise PdfParseError(f"unsupported predictor {predictor}")


def decode_stream(d, raw):
    filt = d.get(b"Filter")
    if filt is None:
        return raw
    if isinstance(filt, bytes):
        filters = [filt]
    else:
        filters = list(filt)
    parms = d.get(b"DecodeParms")
    data = raw
    for i, f in enumerate(filters):
        if not isinstance(f, bytes):
            raise PdfParseError(f"bad filter entry {f!r}")
        if f == b"FlateDecode":
            data = flate_decode(data)
            p = parms[i] if isinstance(parms, list) else parms
            data = apply_predictor(data, p)
        elif f == b"ASCIIHexDecode":
            data = ascii_hex_decode(data)
        elif f == b"ASCII85Decode":
            data = ascii85_decode(data)
        else:
            raise PdfParseError(f"unsupported stream filter {f!r}")
    return data


def parse_classic_xref(data, offset):
    pos = skip_ws(data, offset)
    if data[pos:pos + 4] != b"xref":
        raise PdfParseError("expected 'xref'")
    pos = skip_ws(data, pos + 4)
    entries = {}
    while True:
        m = re.match(rb"(\d+)\s+(\d+)", data[pos:pos + 64])
        if not m:
            break
        start = int(m.group(1))
        count = int(m.group(2))
        pos = skip_ws(data, pos + m.end())
        for _ in range(count):
            mm = re.match(rb"(\d{10}) (\d{5}) ([nf])[ \t]*(?:\r\n|\r|\n)",
                          data[pos:pos + 24])
            if not mm:
                raise PdfParseError(f"bad xref entry near offset {pos}")
            off = int(mm.group(1))
            gen = int(mm.group(2))
            typ = mm.group(3)
            entries[start] = (0, off, gen) if typ == b"f" else (1, off, gen)
            start += 1
            pos += mm.end()
        pos = skip_ws(data, pos)
    if data[pos:pos + 7] != b"trailer":
        raise PdfParseError("expected 'trailer'")
    trailer, _ = parse_dict(data, pos + 7)
    return entries, trailer


def decode_xref_stream(d, raw):
    dec = decode_stream(d, raw)
    w = d.get(b"W")
    if not isinstance(w, list) or len(w) != 3:
        raise PdfParseError("bad /W in xref stream")
    w1, w2, w3 = int(w[0]), int(w[1]), int(w[2])
    idx = d.get(b"Index")
    if idx is None:
        size = int(d.get(b"Size", 0))
        pairs = [(0, size)]
    else:
        pairs = [(int(idx[i]), int(idx[i + 1])) for i in range(0, len(idx), 2)]
    width = w1 + w2 + w3

    def read_int(off, wd):
        val = 0
        for k in range(wd):
            val = (val << 8) | dec[off + k]
        return val

    out = {}
    pos = 0
    for start, count in pairs:
        for i in range(count):
            if pos + width > len(dec):
                raise PdfParseError("xref stream data too short")
            t = read_int(pos, w1) if w1 else 1
            f2 = read_int(pos + w1, w2) if w2 else 0
            f3 = read_int(pos + w1 + w2, w3) if w3 else 0
            pos += width
            if t == 1 and w2 == 0:
                f2 = start + i
            if t == 0:
                out[start + i] = (0, f2, f3)
            elif t == 1:
                out[start + i] = (1, f2, f3)
            elif t == 2:
                out[start + i] = (2, f2, f3)
            else:
                raise PdfParseError(f"bad xref entry type {t}")
    return out


def parse_pdf(data):
    m = list(re.finditer(rb"startxref", data))
    if not m:
        raise PdfParseError("no startxref found")
    offset = None
    for mm in reversed(m):
        pos = skip_ws(data, mm.end())
        mnum = re.match(rb"\d+", data[pos:pos + 32])
        if mnum:
            offset = int(mnum.group(0))
            break
    if offset is None:
        raise PdfParseError("bad startxref")
    sections = []
    trailer = None
    seen = set()
    while offset is not None and offset not in seen and 0 <= offset < len(data):
        seen.add(offset)
        pos = skip_ws(data, offset)
        if data[pos:pos + 4] == b"xref":
            entries, t = parse_classic_xref(data, offset)
            sections.append(entries)
            if trailer is None:
                trailer = t
            xrefstm = t.get(b"XRefStm")
            if isinstance(xrefstm, int):
                try:
                    e2, _ = parse_classic_xref(data, xrefstm)
                    sections.append(e2)
                except PdfParseError:
                    pass
            offset = t.get(b"Prev")
        else:
            onum, ogen, obj, stream = read_object_at_offset(data, offset)
            if not isinstance(obj, dict) or obj.get(b"Type") != b"XRef" or stream is None:
                raise PdfParseError(f"expected xref stream at offset {offset}")
            entries = decode_xref_stream(obj, stream)
            sections.append(entries)
            if trailer is None:
                trailer = obj
            offset = obj.get(b"Prev")
        if offset is not None:
            offset = int(offset)
    if trailer is None:
        raise PdfParseError("no trailer found")
    entries = {}
    for sec in reversed(sections):
        for num, val in sec.items():
            if num not in entries:
                entries[num] = val
    return entries, trailer


def extract_objstm(stm):
    if not isinstance(stm, StreamObj):
        return {}
    d = stm.dict
    if d.get(b"Type") != b"ObjStm":
        return {}
    try:
        dec = decode_stream(d, stm.raw)
    except PdfParseError:
        return {}
    n = d.get(b"N")
    first = d.get(b"First")
    if not isinstance(n, int) or not isinstance(first, int):
        return {}
    toks = []
    pos = 0
    for _ in range(n * 2):
        pos = skip_ws(dec, pos)
        num, pos = parse_number(dec, pos)
        toks.append(int(num))
    out = {}
    for i in range(n):
        objnum = toks[2 * i]
        off = toks[2 * i + 1]
        try:
            val, _ = parse_object(dec, first + off)
        except PdfParseError:
            val = None
        out[objnum] = val
    return out


def load_objects(data, entries):
    objects = {}
    for num, (typ, f2, f3) in entries.items():
        if typ == 1:
            try:
                onum, ogen, obj, stream = read_object_at_offset(data, f2)
                if stream is not None:
                    objects[num] = (f3, StreamObj(obj, stream))
                else:
                    objects[num] = (f3, obj)
            except PdfParseError:
                objects[num] = (f3, None)
    cache = {}
    for num, (typ, f2, f3) in entries.items():
        if typ == 2:
            stm = objects.get(f2)
            if stm is None:
                continue
            if f2 not in cache:
                cache[f2] = extract_objstm(stm)
            embedded = cache[f2]
            if num in embedded:
                objects[num] = (0, embedded[num])
    return objects


def load_pdf(data):
    entries, trailer = parse_pdf(data)
    objects = load_objects(data, entries)
    return entries, trailer, objects


def serialize_string(s):
    out = bytearray(b"(")
    for ch in s:
        if ch in (0x28, 0x29, 0x5C):  # ( ) \
            out += b"\\" + bytes([ch])
        elif 32 <= ch <= 126:
            out.append(ch)
        elif ch == 8:
            out += b"\\b"
        elif ch == 9:
            out += b"\\t"
        elif ch == 10:
            out += b"\\n"
        elif ch == 12:
            out += b"\\f"
        elif ch == 13:
            out += b"\\r"
        else:
            out += b"\\%03o" % ch
    out.append(0x29)
    return bytes(out)


def serialize_value(v):
    if isinstance(v, Ref):
        return b"%d %d R" % (v.num, v.gen)
    if isinstance(v, bool):
        return b"true" if v else b"false"
    if v is None:
        return b"null"
    if isinstance(v, int):
        return b"%d" % v
    if isinstance(v, float):
        return b"%r" % v
    if isinstance(v, bytes):
        return serialize_string(v)
    if isinstance(v, list):
        return b"[" + b" ".join(serialize_value(x) for x in v) + b"]"
    if isinstance(v, dict):
        parts = []
        for k in sorted(v.keys()):
            parts.append(b"/" + k + b" " + serialize_value(v[k]))
        return b"<< " + b" ".join(parts) + b" >>"
    raise PdfParseError(f"cannot serialize {type(v)}")


class PdfBuilder:
    def __init__(self, source_objects):
        self.source_objects = source_objects
        self.objects = {}       # new object number -> structure (or None placeholder)
        self.obj_map = {}       # (old_num, old_gen) -> new number
        self.next_num = 1

    def register(self, structure):
        num = self.next_num
        self.next_num += 1
        self.objects[num] = structure
        return Ref(num, 0)

    def copy_value(self, v):
        if isinstance(v, Ref):
            return self.copy_object(v)
        if isinstance(v, dict):
            return {k: self.copy_value(x) for k, x in v.items()}
        if isinstance(v, list):
            return [self.copy_value(x) for x in v]
        if isinstance(v, StreamObj):
            d = {k: self.copy_value(x) for k, x in v.dict.items()}
            return StreamObj(d, v.raw)
        return v

    def copy_object(self, ref):
        key = (ref.num, ref.gen)
        if key in self.obj_map:
            return Ref(self.obj_map[key], 0)
        src = self.source_objects.get(ref.num)
        if src is None or src[1] is None:
            raise PdfParseError(f"missing object {ref.num}")
        num = self.next_num
        self.next_num += 1
        self.obj_map[key] = num
        copied = self.copy_value(src[1])
        self.objects[num] = copied
        return Ref(num, 0)


# Helvetica glyph widths (units per 1000), ASCII 32..126
HELVETICA_WIDTHS = [
    278, 278, 355, 556, 556, 889, 667, 191, 333, 333, 389, 584, 278, 333, 278, 278,
    556, 556, 556, 556, 556, 556, 556, 556, 556, 556, 278, 278, 584, 584, 584, 556,
    1015, 667, 667, 722, 722, 667, 611, 778, 722, 278, 500, 667, 556, 833, 722, 778,
    667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611, 278, 278, 278, 469, 556,
    333, 556, 556, 500, 556, 556, 278, 556, 556, 222, 222, 500, 222, 833, 556, 556,
    556, 556, 333, 500, 278, 556, 500, 722, 500, 500, 500, 334, 260, 334, 584,
]


def text_width(s, size):
    w = 0
    for ch in s:
        o = ord(ch)
        w += HELVETICA_WIDTHS[o - 32] if 32 <= o <= 126 else 556
    return w * size / 1000.0


def extract_simple_text(data):
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        while i < n and data[i] in b" \t\r\n\f\0":
            i += 1
        if i >= n:
            break
        ch = data[i]
        if data[i:i + 2] == b"BI":  # inline image begin
            j = data.find(b"ID", i + 2)
            if j == -1:
                break
            k = j + 2
            while k < n and data[k] in b" \t\r\n\f\0":
                k += 1
            e = data.find(b"EI", k)
            if e == -1:
                break
            i = e + 2
            continue
        if ch == 0x28:
            s, i2 = parse_literal_string(data, i)
            out += s + b" "
            i = i2
            continue
        if data[i:i + 2] == b"<<":
            i += 2
            continue
        if ch == 0x3C:
            try:
                s, i2 = parse_hex_string(data, i)
            except PdfParseError:
                i += 1
                continue
            out += s + b" "
            i = i2
            continue
        if ch == 0x5B:
            try:
                arr, i2 = parse_array(data, i)
            except PdfParseError:
                i += 1
                continue
            for item in arr:
                if isinstance(item, bytes):
                    out += item + b" "
            i = i2
            continue
        i += 1
    return bytes(out)


def extract_text_from_page(page, objects):
    streams = []

    def add(v):
        if isinstance(v, Ref):
            obj = objects.get(v.num)
            if obj and isinstance(obj[1], StreamObj):
                streams.append(obj[1])
        elif isinstance(v, list):
            for x in v:
                add(x)

    add(page.get(b"Contents"))
    parts = []
    for s in streams:
        try:
            dec = decode_stream(s.dict, s.raw)
        except PdfParseError:
            continue
        parts.append(extract_simple_text(dec))
    return b"\n".join(parts)


if __name__ == "__main__":
    import sys
    from collections import Counter

    path = sys.argv[1] if len(sys.argv) > 1 else "report.pdf"
    try:
        data = open(path, "rb").read()
    except OSError as exc:
        print("error:", exc)
        sys.exit(1)
    print(f"File: {path}  ({len(data)} bytes)")
    m = re.match(rb"%PDF-(\d+\.\d+)", data[:16])
    print("PDF version:", m.group(1).decode() if m else "unknown")
    try:
        entries, trailer, objects = load_pdf(data)
    except PdfParseError as exc:
        print("PARSE FAILED:", exc)
        sys.exit(1)
    print("Xref entries:", len(entries))
    print("Encrypted:", b"Encrypt" in trailer)
    root_ref = trailer.get(b"Root")
    print("Root:", root_ref)
    count = 0
    if isinstance(root_ref, Ref):
        root = objects.get(root_ref.num)
        if root and isinstance(root[1], dict):
            pages_ref = root[1].get(b"Pages")

            def walk(node_ref):
                global count
                node = objects.get(node_ref.num)
                if not node or not isinstance(node[1], dict):
                    return
                d = node[1]
                if d.get(b"Type") == b"Page":
                    count += 1
                elif d.get(b"Kids") is not None:
                    for kid in d[b"Kids"]:
                        if isinstance(kid, Ref):
                            walk(kid)

            if isinstance(pages_ref, Ref):
                walk(pages_ref)
    print("Pages:", count)
    types = Counter()
    filters = Counter()
    streams = 0
    for num, (gen, val) in objects.items():
        if isinstance(val, StreamObj):
            streams += 1
            f = val.dict.get(b"Filter")
            if isinstance(f, bytes):
                filters[f.decode()] += 1
            elif isinstance(f, list):
                for x in f:
                    if isinstance(x, bytes):
                        filters[x.decode()] += 1
            t = val.dict.get(b"Type")
            if isinstance(t, bytes):
                types[t.decode()] += 1
        elif isinstance(val, dict):
            t = val.get(b"Type")
            if isinstance(t, bytes):
                types[t.decode()] += 1
    print("Stream objects:", streams)
    print("Filters:", dict(filters))
    print("Types:", dict(types))

#!/usr/bin/env python3
"""Minimal pure-Python PDF toolkit (stdlib only): parsing, decoding, serialization."""

import re
import zlib


class PdfParseError(Exception):
    pass


class Ref:
    __slots__ = ("num", "gen")

    def __init__(self, num, gen=0):
        self.num = int(num)
        self.gen = int(gen)

    def __repr__(self):
        return f"Ref({self.num},{self.gen})"

    def __hash__(self):
        return hash((self.num, self.gen))

    def __eq__(self, other):
        return isinstance(other, Ref) and self.num == other.num and self.gen == other.gen


class StreamObj:
    __slots__ = ("dict", "raw")

    def __init__(self, d, raw):
        self.dict = d
        self.raw = raw


_WS = b"\x00\t\n\x0c\r "


def skip_ws(data, pos):
    n = len(data)
    while pos < n:
        ch = data[pos]
        if ch in _WS:
            pos += 1
        elif ch == 0x25:  # '%'
            while pos < n and data[pos] not in b"\r\n":
                pos += 1
        else:
            break
    return pos


def parse_number(data, pos):
    n = len(data)
    start = pos
    while pos < n and data[pos] in b"0123456789+-.":
        pos += 1
    tok = data[start:pos]
    if not tok:
        raise PdfParseError("empty number")
    if b"." in tok:
        return float(tok), pos
    return int(tok), pos


def parse_name(data, pos):
    pos += 1
    out = bytearray()
    n = len(data)
    while pos < n:
        ch = data[pos]
        if ch in _WS or ch in b"()<>[]{}/%":
            break
        if ch == 0x23 and pos + 2 < n:  # '#'
            try:
                out.append(int(data[pos + 1:pos + 3], 16))
                pos += 3
                continue
            except ValueError:
                pass
        out.append(ch)
        pos += 1
    return bytes(out), pos


def parse_literal_string(data, pos):
    pos += 1
    out = bytearray()
    depth = 1
    n = len(data)
    while pos < n:
        ch = data[pos]
        if ch == 0x5C:  # backslash
            nxt = data[pos + 1:pos + 2]
            if nxt == b"n":
                out.append(10); pos += 2
            elif nxt == b"r":
                out.append(13); pos += 2
            elif nxt == b"t":
                out.append(9); pos += 2
            elif nxt == b"b":
                out.append(8); pos += 2
            elif nxt == b"f":
                out.append(12); pos += 2
            elif nxt in b"()\\":
                out.append(nxt[0]); pos += 2
            elif nxt in b"01234567":
                j = pos + 1
                val = 0
                k = 0
                while k < 3 and j < n and data[j] in b"01234567":
                    val = val * 8 + (data[j] - 48)
                    j += 1
                    k += 1
                out.append(val & 0xFF)
                pos = j
            elif nxt == b"":
                pos += 1
            elif nxt in (b"\r", b"\n"):
                # line continuation
                if nxt == b"\r" and pos + 2 < n and data[pos + 2] == b"\n":
                    pos += 3
                else:
                    pos += 2
            else:
                out.append(nxt[0]); pos += 2
        elif ch == 0x28:  # (
            depth += 1
            out.append(ch); pos += 1
        elif ch == 0x29:  # )
            depth -= 1
            if depth == 0:
                return bytes(out), pos + 1
            out.append(ch); pos += 1
        else:
            out.append(ch); pos += 1
    raise PdfParseError("unterminated literal string")


def parse_hex_string(data, pos):
    pos += 1
    out = bytearray()
    n = len(data)
    while pos < n and data[pos] != 0x3E:
        ch = data[pos]
        if ch in _WS:
            pos += 1
            continue
        hi = int(chr(ch), 16)
        pos += 1
        if pos < n and data[pos] != 0x3E and data[pos] not in _WS:
            lo = int(chr(data[pos]), 16)
            pos += 1
        else:
            lo = 0
        out.append((hi << 4) | lo)
    if pos >= n:
        raise PdfParseError("unterminated hex string")
    return bytes(out), pos + 1


def parse_array(data, pos):
    pos += 1
    arr = []
    n = len(data)
    while True:
        pos = skip_ws(data, pos)
        if pos >= n:
            raise PdfParseError("unterminated array")
        if data[pos:pos + 1] == b"]":
            return arr, pos + 1
        val, pos = parse_object(data, pos)
        arr.append(val)


def parse_dict(data, pos):
    pos += 2
    d = {}
    n = len(data)
    while True:
        pos = skip_ws(data, pos)
        if pos >= n:
            raise PdfParseError("unterminated dictionary")
        if data[pos:pos + 2] == b">>":
            return d, pos + 2
        key, pos = parse_name(data, pos)
        pos = skip_ws(data, pos)
        val, pos = parse_object(data, pos)
        d[key] = val


def parse_object(data, pos):
    pos = skip_ws(data, pos)
    if pos >= len(data):
        raise PdfParseError("unexpected end of data")
    ch = data[pos]
    if ch == 0x3C:
        if data[pos:pos + 2] == b"<<":
            return parse_dict(data, pos)
        return parse_hex_string(data, pos)
    if ch == 0x5B:
        return parse_array(data, pos)
    if ch == 0x28:
        return parse_literal_string(data, pos)
    if ch == 0x2F:
        return parse_name(data, pos)
    if ch in b"0123456789+-.":
        num, pos2 = parse_number(data, pos)
        pos3 = skip_ws(data, pos2)
        if pos3 < len(data) and data[pos3] in b"0123456789":
            gen, pos4 = parse_number(data, pos3)
            pos5 = skip_ws(data, pos4)
            if pos5 < len(data) and data[pos5] == 0x52:  # 'R'
                if isinstance(num, int) and isinstance(gen, int):
                    return Ref(num, gen), pos5 + 1
        return num, pos2
    if data.startswith(b"true", pos):
        return True, pos + 4
    if data.startswith(b"false", pos):
        return False, pos + 5
    if data.startswith(b"null", pos):
        return None, pos + 4
    raise PdfParseError(f"cannot parse object at offset {pos}: {data[pos:pos + 24]!r}")


def read_object_at_offset(data, offset):
    pos = skip_ws(data, offset)
    num, pos = parse_number(data, pos)
    pos = skip_ws(data, pos)
    gen, pos = parse_number(data, pos)
    pos = skip_ws(data, pos)
    if data[pos:pos + 3] != b"obj":
        raise PdfParseError(f"expected 'obj' at offset {offset}")
    pos += 3
    obj, pos = parse_object(data, pos)
    stream = None
    pos2 = skip_ws(data, pos)
    if data[pos2:pos2 + 6] == b"stream":
        p = pos2 + 6
        if data[p:p + 2] == b"\r\n":
            p += 2
        elif data[p:p + 1] in (b"\n", b"\r"):
            p += 1
        length = None
        if isinstance(obj, dict) and isinstance(obj.get(b"Length"), int):
            length = obj[b"Length"]
        if length is not None and p + length <= len(data):
            stream = data[p:p + length]
        else:
            e = data.find(b"endstream", p)
            if e == -1:
                raise PdfParseError("endstream not found")
            stream = data[p:e]
    return num, gen, obj, stream


def flate_decode(data):
    try:
        return zlib.decompress(data)
    except zlib.error:
        d = zlib.decompressobj(-15)
        return d.decompress(data) + d.flush()


def ascii85_decode(data):
    out = bytearray()
    buf = []
    for ch in data:
        if ch in b" \t\r\n\0":
            continue
        if ch == 0x7E:  # '~'
            break
        if ch == 0x7A and not buf:  # 'z'
            out += b"\x00\x00\x00\x00"
            continue
        if 0x21 <= ch <= 0x75:
            buf.append(ch - 33)
            if len(buf) == 5:
                val = 0
                for b in buf:
                    val = val * 85 + b
                out += val.to_bytes(4, "big")
                buf = []
        else:
            raise PdfParseError("bad ascii85 char")
    if buf:
        pad = 5 - len(buf)
        buf += [84] * pad
        val = 0
        for b in buf:
            val = val * 85 + b
        raw = val.to_bytes(4, "big")
        out += raw[:5 - pad]
    return bytes(out)


def ascii_hex_decode(data):
    out = bytearray()
    digits = bytearray()
    for ch in data:
        if ch in b" \t\r\n\0":
            continue
        if ch == 0x3E:
            break
        digits.append(ch)
    if len(digits) % 2:
        digits.append(0x30)
    for i in range(0, len(digits), 2):
        out.append((int(chr(digits[i]), 16) << 4) | int(chr(digits[i + 1]), 16))
    return bytes(out)


def apply_predictor(data, parms):
    if not isinstance(parms, dict):
        return data
    predictor = parms.get(b"Predictor", 1)
    if not isinstance(predictor, int) or predictor <= 1:
        return data
    colors = parms.get(b"Colors", 1)
    bpc = parms.get(b"BitsPerComponent", 8)
    columns = parms.get(b"Columns", 1)
    if not all(isinstance(x, int) for x in (colors, bpc, columns)):
        return data
    if bpc != 8:
        raise PdfParseError(f"unsupported predictor bpc {bpc}")
    bpp = max(1, (colors * bpc + 7) // 8)
    rowlen = (colors * bpc * columns + 7) // 8
    if predictor == 2:  # TIFF
        out = bytearray()
        for off in range(0, len(data), rowlen):
            row = bytearray(data[off:off + rowlen])
            for i in range(bpp, rowlen):
                row[i] = (row[i] + row[i - bpp]) & 0xFF
            out += row
        return bytes(out)
    if 10 <= predictor <= 15:  # PNG
        out = bytearray()
        prev = bytearray(rowlen)
        pos = 0
        while pos < len(data):
            ft = data[pos]
            pos += 1
            row = bytearray(data[pos:pos + rowlen])
            pos += rowlen
            if ft == 1:
                for i in range(bpp, rowlen):
                    row[i] = (row[i] + row[i - bpp]) & 0xFF
            elif ft == 2:
                for i in range(rowlen):
                    row[i] = (row[i] + prev[i]) & 0xFF
            elif ft == 3:
                for i in range(rowlen):
                    left = row[i - bpp] if i >= bpp else 0
                    row[i] = (row[i] + ((left + prev[i]) >> 1)) & 0xFF
            elif ft == 4:
                for i in range(rowlen):
                    left = row[i - bpp] if i >= bpp else 0
                    up = prev[i]
                    ul = prev[i - bpp] if i >= bpp else 0
                    p = left + up - ul
                    pa = abs(p - left); pb = abs(p - up); pc = abs(p - ul)
                    if pa <= pb and pa <= pc:
                        pr = left
                    elif pb <= pc:
                        pr = up
                    else:
                        pr = ul
                    row[i] = (row[i] + pr) & 0xFF
            elif ft != 0:
                raise PdfParseError(f"unknown PNG predictor {ft}")
            out += row
            prev = row
        return bytes(out)
    raise PdfParseError(f"unsupported predictor {predictor}")


def decode_stream(d, raw):
    filt = d.get(b"Filter")
    if filt is None:
        return raw
    if isinstance(filt, bytes):
        filters = [filt]
    else:
        filters = list(filt)
    parms = d.get(b"DecodeParms")
    data = raw
    for i, f in enumerate(filters):
        if not isinstance(f, bytes):
            raise PdfParseError(f"bad filter entry {f!r}")
        if f == b"FlateDecode":
            data = flate_decode(data)
            p = parms[i] if isinstance(parms, list) else parms
            data = apply_predictor(data, p)
        elif f == b"ASCIIHexDecode":
            data = ascii_hex_decode(data)
        elif f == b"ASCII85Decode":
            data = ascii85_decode(data)
        else:
            raise PdfParseError(f"unsupported stream filter {f!r}")
    return data


def parse_classic_xref(data, offset):
    pos = skip_ws(data, offset)
    if data[pos:pos + 4] != b"xref":
        raise PdfParseError("expected 'xref'")
    pos = skip_ws(data, pos + 4)
    entries = {}
    while True:
        m = re.match(rb"(\d+)\s+(\d+)", data[pos:pos + 64])
        if not m:
            break
        start = int(m.group(1))
        count = int(m.group(2))
        pos += m.end()
        for _ in range(count):
            mm = re.match(rb"(\d{10}) (\d{5}) ([nf])[ \t]*(?:\r\n|\r|\n)",
                          data[pos:pos + 24])
            if not mm:
                raise PdfParseError(f"bad xref entry near offset {pos}")
            off = int(mm.group(1))
            gen = int(mm.group(2))
            typ = mm.group(3)
            entries[start] = (0, off, gen) if typ == b"f" else (1, off, gen)
            start += 1
            pos += mm.end()
        pos = skip_ws(data, pos)
    if data[pos:pos + 7] != b"trailer":
        raise PdfParseError("expected 'trailer'")
    trailer, _ = parse_dict(data, pos + 7)
    return entries, trailer


def decode_xref_stream(d, raw):
    dec = decode_stream(d, raw)
    w = d.get(b"W")
    if not isinstance(w, list) or len(w) != 3:
        raise PdfParseError("bad /W in xref stream")
    w1, w2, w3 = int(w[0]), int(w[1]), int(w[2])
    idx = d.get(b"Index")
    if idx is None:
        size = int(d.get(b"Size", 0))
        pairs = [(0, size)]
    else:
        pairs = [(int(idx[i]), int(idx[i + 1])) for i in range(0, len(idx), 2)]
    width = w1 + w2 + w3

    def read_int(off, wd):
        val = 0
        for k in range(wd):
            val = (val << 8) | dec[off + k]
        return val

    out = {}
    pos = 0
    for start, count in pairs:
        for i in range(count):
            if pos + width > len(dec):
                raise PdfParseError("xref stream data too short")
            t = read_int(pos, w1) if w1 else 1
            f2 = read_int(pos + w1, w2) if w2 else 0
            f3 = read_int(pos + w1 + w2, w3) if w3 else 0
            pos += width
            if t == 1 and w2 == 0:
                f2 = start + i
            if t == 0:
                out[start + i] = (0, f2, f3)
            elif t == 1:
                out[start + i] = (1, f2, f3)
            elif t == 2:
                out[start + i] = (2, f2, f3)
            else:
                raise PdfParseError(f"bad xref entry type {t}")
    return out


def parse_pdf(data):
    m = list(re.finditer(rb"startxref", data))
    if not m:
        raise PdfParseError("no startxref found")
    offset = None
    for mm in reversed(m):
        pos = skip_ws(data, mm.end())
        mnum = re.match(rb"\d+", data[pos:pos + 32])
        if mnum:
            offset = int(mnum.group(0))
            break
    if offset is None:
        raise PdfParseError("bad startxref")
    sections = []
    trailer = None
    seen = set()
    while offset is not None and offset not in seen and 0 <= offset < len(data):
        seen.add(offset)
        pos = skip_ws(data, offset)
        if data[pos:pos + 4] == b"xref":
            entries, t = parse_classic_xref(data, offset)
            sections.append(entries)
            if trailer is None:
                trailer = t
            xrefstm = t.get(b"XRefStm")
            if isinstance(xrefstm, int):
                try:
                    e2, _ = parse_classic_xref(data, xrefstm)
                    sections.append(e2)
                except PdfParseError:
                    pass
            offset = t.get(b"Prev")
        else:
            onum, ogen, obj, stream = read_object_at_offset(data, offset)
            if not isinstance(obj, dict) or obj.get(b"Type") != b"XRef" or stream is None:
                raise PdfParseError(f"expected xref stream at offset {offset}")
            entries = decode_xref_stream(obj, stream)
            sections.append(entries)
            if trailer is None:
                trailer = obj
            offset = obj.get(b"Prev")
        if offset is not None:
            offset = int(offset)
    if trailer is None:
        raise PdfParseError("no trailer found")
    entries = {}
    for sec in reversed(sections):
        for num, val in sec.items():
            if num not in entries:
                entries[num] = val
    return entries, trailer


def extract_objstm(stm):
    if not isinstance(stm, StreamObj):
        return {}
    d = stm.dict
    if d.get(b"Type") != b"ObjStm":
        return {}
    try:
        dec = decode_stream(d, stm.raw)
    except PdfParseError:
        return {}
    n = d.get(b"N")
    first = d.get(b"First")
    if not isinstance(n, int) or not isinstance(first, int):
        return {}
    toks = []
    pos = 0
    for _ in range(n * 2):
        pos = skip_ws(dec, pos)
        num, pos = parse_number(dec, pos)
        toks.append(int(num))
    out = {}
    for i in range(n):
        objnum = toks[2 * i]
        off = toks[2 * i + 1]
        try:
            val, _ = parse_object(dec, first + off)
        except PdfParseError:
            val = None
        out[objnum] = val
    return out


def load_objects(data, entries):
    objects = {}
    for num, (typ, f2, f3) in entries.items():
        if typ == 1:
            try:
                onum, ogen, obj, stream = read_object_at_offset(data, f2)
                if stream is not None:
                    objects[num] = (f3, StreamObj(obj, stream))
                else:
                    objects[num] = (f3, obj)
            except PdfParseError:
                objects[num] = (f3, None)
    cache = {}
    for num, (typ, f2, f3) in entries.items():
        if typ == 2:
            stm = objects.get(f2)
            if stm is None:
                continue
            if f2 not in cache:
                cache[f2] = extract_objstm(stm)
            embedded = cache[f2]
            if num in embedded:
                objects[num] = (0, embedded[num])
    return objects


def load_pdf(data):
    entries, trailer = parse_pdf(data)
    objects = load_objects(data, entries)
    return entries, trailer, objects


def serialize_string(s):
    out = bytearray(b"(")
    for ch in s:
        if ch in (0x28, 0x29, 0x5C):  # ( ) \
            out += b"\\" + bytes([ch])
        elif 32 <= ch <= 126:
            out.append(ch)
        elif ch == 8:
            out += b"\\b"
        elif ch == 9:
            out += b"\\t"
        elif ch == 10:
            out += b"\\n"
        elif ch == 12:
            out += b"\\f"
        elif ch == 13:
            out += b"\\r"
        else:
            out += b"\\%03o" % ch
    out.append(0x29)
    return bytes(out)


def serialize_value(v):
    if isinstance(v, Ref):
        return b"%d %d R" % (v.num, v.gen)
    if isinstance(v, bool):
        return b"true" if v else b"false"
    if v is None:
        return b"null"
    if isinstance(v, int):
        return b"%d" % v
    if isinstance(v, float):
        return b"%r" % v
    if isinstance(v, bytes):
        return serialize_string(v)
    if isinstance(v, list):
        return b"[" + b" ".join(serialize_value(x) for x in v) + b"]"
    if isinstance(v, dict):
        parts = []
        for k in sorted(v.keys()):
            parts.append(b"/" + k + b" " + serialize_value(v[k]))
        return b"<< " + b" ".join(parts) + b" >>"
    raise PdfParseError(f"cannot serialize {type(v)}")


class PdfBuilder:
    def __init__(self, source_objects):
        self.source_objects = source_objects
        self.objects = {}       # new object number -> structure (or None placeholder)
        self.obj_map = {}       # (old_num, old_gen) -> new number
        self.next_num = 1

    def register(self, structure):
        num = self.next_num
        self.next_num += 1
        self.objects[num] = structure
        return Ref(num, 0)

    def copy_value(self, v):
        if isinstance(v, Ref):
            return self.copy_object(v)
        if isinstance(v, dict):
            return {k: self.copy_value(x) for k, x in v.items()}
        if isinstance(v, list):
            return [self.copy_value(x) for x in v]
        if isinstance(v, StreamObj):
            d = {k: self.copy_value(x) for k, x in v.dict.items()}
            return StreamObj(d, v.raw)
        return v

    def copy_object(self, ref):
        key = (ref.num, ref.gen)
        if key in self.obj_map:
            return Ref(self.obj_map[key], 0)
        src = self.source_objects.get(ref.num)
        if src is None or src[1] is None:
            raise PdfParseError(f"missing object {ref.num}")
        num = self.next_num
        self.next_num += 1
        self.obj_map[key] = num
        copied = self.copy_value(src[1])
        self.objects[num] = copied
        return Ref(num, 0)


# Helvetica glyph widths (units per 1000), ASCII 32..126
HELVETICA_WIDTHS = [
    278, 278, 355, 556, 556, 889, 667, 191, 333, 333, 389, 584, 278, 333, 278, 278,
    556, 556, 556, 556, 556, 556, 556, 556, 556, 556, 278, 278, 584, 584, 584, 556,
    1015, 667, 667, 722, 722, 667, 611, 778, 722, 278, 500, 667, 556, 833, 722, 778,
    667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611, 278, 278, 278, 469, 556,
    333, 556, 556, 500, 556, 556, 278, 556, 556, 222, 222, 500, 222, 833, 556, 556,
    556, 556, 333, 500, 278, 556, 500, 722, 500, 500, 500, 334, 260, 334, 584,
]


def text_width(s, size):
    w = 0
    for ch in s:
        o = ord(ch)
        w += HELVETICA_WIDTHS[o - 32] if 32 <= o <= 126 else 556
    return w * size / 1000.0


def extract_simple_text(data):
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        while i < n and data[i] in b" \t\r\n\f\0":
            i += 1
        if i >= n:
            break
        ch = data[i]
        if data[i:i + 2] == b"BI":  # inline image begin
            j = data.find(b"ID", i + 2)
            if j == -1:
                break
            k = j + 2
            while k < n and data[k] in b" \t\r\n\f\0":
                k += 1
            e = data.find(b"EI", k)
            if e == -1:
                break
            i = e + 2
            continue
        if ch == 0x28:
            s, i2 = parse_literal_string(data, i)
            out += s + b" "
            i = i2
            continue
        if data[i:i + 2] == b"<<":
            i += 2
            continue
        if ch == 0x3C:
            try:
                s, i2 = parse_hex_string(data, i)
            except PdfParseError:
                i += 1
                continue
            out += s + b" "
            i = i2
            continue
        if ch == 0x5B:
            try:
                arr, i2 = parse_array(data, i)
            except PdfParseError:
                i += 1
                continue
            for item in arr:
                if isinstance(item, bytes):
                    out += item + b" "
            i = i2
            continue
        i += 1
    return bytes(out)


def extract_text_from_page(page, objects):
    streams = []

    def add(v):
        if isinstance(v, Ref):
            obj = objects.get(v.num)
            if obj and isinstance(obj[1], StreamObj):
                streams.append(obj[1])
        elif isinstance(v, list):
            for x in v:
                add(x)

    add(page.get(b"Contents"))
    parts = []
    for s in streams:
        try:
            dec = decode_stream(s.dict, s.raw)
        except PdfParseError:
            continue
        parts.append(extract_simple_text(dec))
    return b"\n".join(parts)


if __name__ == "__main__":
    import sys
    from collections import Counter

    path = sys.argv[1] if len(sys.argv) > 1 else "report.pdf"
    try:
        data = open(path, "rb").read()
    except OSError as exc:
        print("error:", exc)
        sys.exit(1)
    print(f"File: {path}  ({len(data)} bytes)")
    m = re.match(rb"%PDF-(\d+\.\d+)", data[:16])
    print("PDF version:", m.group(1).decode() if m else "unknown")
    try:
        entries, trailer, objects = load_pdf(data)
    except PdfParseError as exc:
        print("PARSE FAILED:", exc)
        sys.exit(1)
    print("Xref entries:", len(entries))
    print("Encrypted:", b"Encrypt" in trailer)
    root_ref = trailer.get(b"Root")
    print("Root:", root_ref)
    count = 0
    if isinstance(root_ref, Ref):
        root = objects.get(root_ref.num)
        if root and isinstance(root[1], dict):
            pages_ref = root[1].get(b"Pages")

            def walk(node_ref):
                global count
                node = objects.get(node_ref.num)
                if not node or not isinstance(node[1], dict):
                    return
                d = node[1]
                if d.get(b"Type") == b"Page":
                    count += 1
                elif d.get(b"Kids") is not None:
                    for kid in d[b"Kids"]:
                        if isinstance(kid, Ref):
                            walk(kid)

            if isinstance(pages_ref, Ref):
                walk(pages_ref)
    print("Pages:", count)
    types = Counter()
    filters = Counter()
    streams = 0
    for num, (gen, val) in objects.items():
        if isinstance(val, StreamObj):
            streams += 1
            f = val.dict.get(b"Filter")
            if isinstance(f, bytes):
                filters[f.decode()] += 1
            elif isinstance(f, list):
                for x in f:
                    if isinstance(x, bytes):
                        filters[x.decode()] += 1
            t = val.dict.get(b"Type")
            if isinstance(t, bytes):
                types[t.decode()] += 1
        elif isinstance(val, dict):
            t = val.get(b"Type")
            if isinstance(t, bytes):
                types[t.decode()] += 1
    print("Stream objects:", streams)
    print("Filters:", dict(filters))
    print("Types:", dict(types))

#!/usr/bin/env python3
"""Minimal pure-Python PDF toolkit (stdlib only): parsing, decoding, serialization."""

import re
import zlib


class PdfParseError(Exception):
    pass


class Ref:
    __slots__ = ("num", "gen")

    def __init__(self, num, gen=0):
        self.num = int(num)
        self.gen = int(gen)

    def __repr__(self):
        return f"Ref({self.num},{self.gen})"

    def __hash__(self):
        return hash((self.num, self.gen))

    def __eq__(self, other):
        return isinstance(other, Ref) and self.num == other.num and self.gen == other.gen


class StreamObj:
    __slots__ = ("dict", "raw")

    def __init__(self, d, raw):
        self.dict = d
        self.raw = raw


_WS = b"\x00\t\n\x0c\r "


def skip_ws(data, pos):
    n = len(data)
    while pos < n:
        ch = data[pos]
        if ch in _WS:
            pos += 1
        elif ch == 0x25:  # '%'
            while pos < n and data[pos] not in b"\r\n":
                pos += 1
        else:
            break
    return pos


def parse_number(data, pos):
    n = len(data)
    start = pos
    while pos < n and data[pos] in b"0123456789+-.":
        pos += 1
    tok = data[start:pos]
    if not tok:
        raise PdfParseError("empty number")
    if b"." in tok:
        return float(tok), pos
    return int(tok), pos


def parse_name(data, pos):
    pos += 1
    out = bytearray()
    n = len(data)
    while pos < n:
        ch = data[pos]
        if ch in _WS or ch in b"()<>[]{}/%":
            break
        if ch == 0x23 and pos + 2 < n:  # '#'
            try:
                out.append(int(data[pos + 1:pos + 3], 16))
                pos += 3
                continue
            except ValueError:
                pass
        out.append(ch)
        pos += 1
    return bytes(out), pos


def parse_literal_string(data, pos):
    pos += 1
    out = bytearray()
    depth = 1
    n = len(data)
    while pos < n:
        ch = data[pos]
        if ch == 0x5C:  # backslash
            nxt = data[pos + 1:pos + 2]
            if nxt == b"n":
                out.append(10); pos += 2
            elif nxt == b"r":
                out.append(13); pos += 2
            elif nxt == b"t":
                out.append(9); pos += 2
            elif nxt == b"b":
                out.append(8); pos += 2
            elif nxt == b"f":
                out.append(12); pos += 2
            elif nxt in b"()\\":
                out.append(nxt[0]); pos += 2
            elif nxt in b"01234567":
                j = pos + 1
                val = 0
                k = 0
                while k < 3 and j < n and data[j] in b"01234567":
                    val = val * 8 + (data[j] - 48)
                    j += 1
                    k += 1
                out.append(val & 0xFF)
                pos = j
            elif nxt == b"":
                pos += 1
            elif nxt in (b"\r", b"\n"):
                # line continuation
                if nxt == b"\r" and pos + 2 < n and data[pos + 2] == b"\n":
                    pos += 3
                else:
                    pos += 2
            else:
                out.append(nxt[0]); pos += 2
        elif ch == 0x28:  # (
            depth += 1
            out.append(ch); pos += 1
        elif ch == 0x29:  # )
            depth -= 1
            if depth == 0:
                return bytes(out), pos + 1
            out.append(ch); pos += 1
        else:
            out.append(ch); pos += 1
    raise PdfParseError("unterminated literal string")


def parse_hex_string(data, pos):
    pos += 1
    out = bytearray()
    n = len(data)
    while pos < n and data[pos] != 0x3E:
        ch = data[pos]
        if ch in _WS:
            pos += 1
            continue
        hi = int(chr(ch), 16)
        pos += 1
        if pos < n and data[pos] != 0x3E and data[pos] not in _WS:
            lo = int(chr(data[pos]), 16)
            pos += 1
        else:
            lo = 0
        out.append((hi << 4) | lo)
    if pos >= n:
        raise PdfParseError("unterminated hex string")
    return bytes(out), pos + 1


def parse_array(data, pos):
    pos += 1
    arr = []
    n = len(data)
    while True:
        pos = skip_ws(data, pos)
        if pos >= n:
            raise PdfParseError("unterminated array")
        if data[pos:pos + 1] == b"]":
            return arr, pos + 1
        val, pos = parse_object(data, pos)
        arr.append(val)


def parse_dict(data, pos):
    pos += 2
    d = {}
    n = len(data)
    while True:
        pos = skip_ws(data, pos)
        if pos >= n:
            raise PdfParseError("unterminated dictionary")
        if data[pos:pos + 2] == b">>":
            return d, pos + 2
        key, pos = parse_name(data, pos)
        pos = skip_ws(data, pos)
        val, pos = parse_object(data, pos)
        d[key] = val


def parse_object(data, pos):
    pos = skip_ws(data, pos)
    if pos >= len(data):
        raise PdfParseError("unexpected end of data")
    ch = data[pos]
    if ch == 0x3C:
        if data[pos:pos + 2] == b"<<":
            return parse_dict(data, pos)
        return parse_hex_string(data, pos)
    if ch == 0x5B:
        return parse_array(data, pos)
    if ch == 0x28:
        return parse_literal_string(data, pos)
    if ch == 0x2F:
        return parse_name(data, pos)
    if ch in b"0123456789+-.":
        num, pos2 = parse_number(data, pos)
        pos3 = skip_ws(data, pos2)
        if pos3 < len(data) and data[pos3] in b"0123456789":
            gen, pos4 = parse_number(data, pos3)
            pos5 = skip_ws(data, pos4)
            if pos5 < len(data) and data[pos5] == 0x52:  # 'R'
                if isinstance(num, int) and isinstance(gen, int):
                    return Ref(num, gen), pos5 + 1
        return num, pos2
    if data.startswith(b"true", pos):
        return True, pos + 4
    if data.startswith(b"false", pos):
        return False, pos + 5
    if data.startswith(b"null", pos):
        return None, pos + 4
    raise PdfParseError(f"cannot parse object at offset {pos}: {data[pos:pos + 24]!r}")


def read_object_at_offset(data, offset):
    pos = skip_ws(data, offset)
    num, pos = parse_number(data, pos)
    pos = skip_ws(data, pos)
    gen, pos = parse_number(data, pos)
    pos = skip_ws(data, pos)
    if data[pos:pos + 3] != b"obj":
        raise PdfParseError(f"expected 'obj' at offset {offset}")
    pos += 3
    obj, pos = parse_object(data, pos)
    stream = None
    pos2 = skip_ws(data, pos)
    if data[pos2:pos2 + 6] == b"stream":
        p = pos2 + 6
        if data[p:p + 2] == b"\r\n":
            p += 2
        elif data[p:p + 1] in (b"\n", b"\r"):
            p += 1
        length = None
        if isinstance(obj, dict) and isinstance(obj.get(b"Length"), int):
            length = obj[b"Length"]
        if length is not None and p + length <= len(data):
            stream = data[p:p + length]
        else:
            e = data.find(b"endstream", p)
            if e == -1:
                raise PdfParseError("endstream not found")
            stream = data[p:e]
    return num, gen, obj, stream


def flate_decode(data):
    try:
        return zlib.decompress(data)
    except zlib.error:
        d = zlib.decompressobj(-15)
        return d.decompress(data) + d.flush()


def ascii85_decode(data):
    out = bytearray()
    buf = []
    for ch in data:
        if ch in b" \t\r\n\0":
            continue
        if ch == 0x7E:  # '~'
            break
        if ch == 0x7A and not buf:  # 'z'
            out += b"\x00\x00\x00\x00"
            continue
        if 0x21 <= ch <= 0x75:
            buf.append(ch - 33)
            if len(buf) == 5:
                val = 0
                for b in buf:
                    val = val * 85 + b
                out += val.to_bytes(4, "big")
                buf = []
        else:
            raise PdfParseError("bad ascii85 char")
    if buf:
        pad = 5 - len(buf)
        buf += [84] * pad
        val = 0
        for b in buf:
            val = val * 85 + b
        raw = val.to_bytes(4, "big")
        out += raw[:5 - pad]
    return bytes(out)


def ascii_hex_decode(data):
    out = bytearray()
    digits = bytearray()
    for ch in data:
        if ch in b" \t\r\n\0":
            continue
        if ch == 0x3E:
            break
        digits.append(ch)
    if len(digits) % 2:
        digits.append(0x30)
    for i in range(0, len(digits), 2):
        out.append((int(chr(digits[i]), 16) << 4) | int(chr(digits[i + 1]), 16))
    return bytes(out)


def apply_predictor(data, parms):
    if not isinstance(parms, dict):
        return data
    predictor = parms.get(b"Predictor", 1)
    if not isinstance(predictor, int) or predictor <= 1:
        return data
    colors = parms.get(b"Colors", 1)
    bpc = parms.get(b"BitsPerComponent", 8)
    columns = parms.get(b"Columns", 1)
    if not all(isinstance(x, int) for x in (colors, bpc, columns)):
        return data
    if bpc != 8:
        raise PdfParseError(f"unsupported predictor bpc {bpc}")
    bpp = max(1, (colors * bpc + 7) // 8)
    rowlen = (colors * bpc * columns + 7) // 8
    if predictor == 2:  # TIFF
        out = bytearray()
        for off in range(0, len(data), rowlen):
            row = bytearray(data[off:off + rowlen])
            for i in range(bpp, rowlen):
                row[i] = (row[i] + row[i - bpp]) & 0xFF
            out += row
        return bytes(out)
    if 10 <= predictor <= 15:  # PNG
        out = bytearray()
        prev = bytearray(rowlen)
        pos = 0
        while pos < len(data):
            ft = data[pos]
            pos += 1
            row = bytearray(data[pos:pos + rowlen])
            pos += rowlen
            if ft == 1:
                for i in range(bpp, rowlen):
                    row[i] = (row[i] + row[i - bpp]) & 0xFF
            elif ft == 2:
                for i in range(rowlen):
                    row[i] = (row[i] + prev[i]) & 0xFF
            elif ft == 3:
                for i in range(rowlen):
                    left = row[i - bpp] if i >= bpp else 0
                    row[i] = (row[i] + ((left + prev[i]) >> 1)) & 0xFF
            elif ft == 4:
                for i in range(rowlen):
                    left = row[i - bpp] if i >= bpp else 0
                    up = prev[i]
                    ul = prev[i - bpp] if i >= bpp else 0
                    p = left + up - ul
                    pa = abs(p - left); pb = abs(p - up); pc = abs(p - ul)
                    if pa <= pb and pa <= pc:
                        pr = left
                    elif pb <= pc:
                        pr = up
                    else:
                        pr = ul
                    row[i] = (row[i] + pr) & 0xFF
            elif ft != 0:
                raise PdfParseError(f"unknown PNG predictor {ft}")
            out += row
            prev = row
        return bytes(out)
    raise PdfParseError(f"unsupported predictor {predictor}")


def decode_stream(d, raw):
    filt = d.get(b"Filter")
    if filt is None:
        return raw
    if isinstance(filt, bytes):
        filters = [filt]
    else:
        filters = list(filt)
    parms = d.get(b"DecodeParms")
    data = raw
    for i, f in enumerate(filters):
        if not isinstance(f, bytes):
            raise PdfParseError(f"bad filter entry {f!r}")
        if f == b"FlateDecode":
            data = flate_decode(data)
            p = parms[i] if isinstance(parms, list) else parms
            data = apply_predictor(data, p)
        elif f == b"ASCIIHexDecode":
            data = ascii_hex_decode(data)
        elif f == b"ASCII85Decode":
            data = ascii85_decode(data)
        else:
            raise PdfParseError(f"unsupported stream filter {f!r}")
    return data


def parse_classic_xref(data, offset):
    pos = skip_ws(data, offset)
    if data[pos:pos + 4] != b"xref":
        raise PdfParseError("expected 'xref'")
    pos = skip_ws(data, pos + 4)
    entries = {}
    while True:
        m = re.match(rb"(\d+)\s+(\d+)", data[pos:pos + 64])
        if not m:
            break
        start = int(m.group(1))
        count = int(m.group(2))
        pos = skip_ws(data, pos + m.end())
        for _ in range(count):
            mm = re.match(rb"(\d{10}) (\d{5}) ([nf])[ \t]*(?:\r\n|\r|\n)",
                          data[pos:pos + 24])
            if not mm:
                raise PdfParseError(f"bad xref entry near offset {pos}")
            off = int(mm.group(1))
            gen = int(mm.group(2))
            typ = mm.group(3)
            entries[start] = (0, off, gen) if typ == b"f" else (1, off, gen)
            start += 1
            pos += mm.end()
        pos = skip_ws(data, pos)
    if data[pos:pos + 7] != b"trailer":
        raise PdfParseError("expected 'trailer'")
    trailer, _ = parse_dict(data, pos + 7)
    return entries, trailer


def decode_xref_stream(d, raw):
    dec = decode_stream(d, raw)
    w = d.get(b"W")
    if not isinstance(w, list) or len(w) != 3:
        raise PdfParseError("bad /W in xref stream")
    w1, w2, w3 = int(w[0]), int(w[1]), int(w[2])
    idx = d.get(b"Index")
    if idx is None:
        size = int(d.get(b"Size", 0))
        pairs = [(0, size)]
    else:
        pairs = [(int(idx[i]), int(idx[i + 1])) for i in range(0, len(idx), 2)]
    width = w1 + w2 + w3

    def read_int(off, wd):
        val = 0
        for k in range(wd):
            val = (val << 8) | dec[off + k]
        return val

    out = {}
    pos = 0
    for start, count in pairs:
        for i in range(count):
            if pos + width > len(dec):
                raise PdfParseError("xref stream data too short")
            t = read_int(pos, w1) if w1 else 1
            f2 = read_int(pos + w1, w2) if w2 else 0
            f3 = read_int(pos + w1 + w2, w3) if w3 else 0
            pos += width
            if t == 1 and w2 == 0:
                f2 = start + i
            if t == 0:
                out[start + i] = (0, f2, f3)
            elif t == 1:
                out[start + i] = (1, f2, f3)
            elif t == 2:
                out[start + i] = (2, f2, f3)
            else:
                raise PdfParseError(f"bad xref entry type {t}")
    return out


def parse_pdf(data):
    m = list(re.finditer(rb"startxref", data))
    if not m:
        raise PdfParseError("no startxref found")
    offset = None
    for mm in reversed(m):
        pos = skip_ws(data, mm.end())
        mnum = re.match(rb"\d+", data[pos:pos + 32])
        if mnum:
            offset = int(mnum.group(0))
            break
    if offset is None:
        raise PdfParseError("bad startxref")
    sections = []
    trailer = None
    seen = set()
    while offset is not None and offset not in seen and 0 <= offset < len(data):
        seen.add(offset)
        pos = skip_ws(data, offset)
        if data[pos:pos + 4] == b"xref":
            entries, t = parse_classic_xref(data, offset)
            sections.append(entries)
            if trailer is None:
                trailer = t
            xrefstm = t.get(b"XRefStm")
            if isinstance(xrefstm, int):
                try:
                    e2, _ = parse_classic_xref(data, xrefstm)
                    sections.append(e2)
                except PdfParseError:
                    pass
            offset = t.get(b"Prev")
        else:
            onum, ogen, obj, stream = read_object_at_offset(data, offset)
            if not isinstance(obj, dict) or obj.get(b"Type") != b"XRef" or stream is None:
                raise PdfParseError(f"expected xref stream at offset {offset}")
            entries = decode_xref_stream(obj, stream)
            sections.append(entries)
            if trailer is None:
                trailer = obj
            offset = obj.get(b"Prev")
        if offset is not None:
            offset = int(offset)
    if trailer is None:
        raise PdfParseError("no trailer found")
    entries = {}
    for sec in reversed(sections):
        for num, val in sec.items():
            if num not in entries:
                entries[num] = val
    return entries, trailer


def extract_objstm(stm):
    if not isinstance(stm, StreamObj):
        return {}
    d = stm.dict
    if d.get(b"Type") != b"ObjStm":
        return {}
    try:
        dec = decode_stream(d, stm.raw)
    except PdfParseError:
        return {}
    n = d.get(b"N")
    first = d.get(b"First")
    if not isinstance(n, int) or not isinstance(first, int):
        return {}
    toks = []
    pos = 0
    for _ in range(n * 2):
        pos = skip_ws(dec, pos)
        num, pos = parse_number(dec, pos)
        toks.append(int(num))
    out = {}
    for i in range(n):
        objnum = toks[2 * i]
        off = toks[2 * i + 1]
        try:
            val, _ = parse_object(dec, first + off)
        except PdfParseError:
            val = None
        out[objnum] = val
    return out


def load_objects(data, entries):
    objects = {}
    for num, (typ, f2, f3) in entries.items():
        if typ == 1:
            try:
                onum, ogen, obj, stream = read_object_at_offset(data, f2)
                if stream is not None:
                    objects[num] = (f3, StreamObj(obj, stream))
                else:
                    objects[num] = (f3, obj)
            except PdfParseError:
                objects[num] = (f3, None)
    cache = {}
    for num, (typ, f2, f3) in entries.items():
        if typ == 2:
            stm = objects.get(f2)
            if stm is None:
                continue
            if f2 not in cache:
                cache[f2] = extract_objstm(stm)
            embedded = cache[f2]
            if num in embedded:
                objects[num] = (0, embedded[num])
    return objects


def load_pdf(data):
    entries, trailer = parse_pdf(data)
    objects = load_objects(data, entries)
    return entries, trailer, objects


def serialize_string(s):
    out = bytearray(b"(")
    for ch in s:
        if ch in (0x28, 0x29, 0x5C):  # ( ) \
            out += b"\\" + bytes([ch])
        elif 32 <= ch <= 126:
            out.append(ch)
        elif ch == 8:
            out += b"\\b"
        elif ch == 9:
            out += b"\\t"
        elif ch == 10:
            out += b"\\n"
        elif ch == 12:
            out += b"\\f"
        elif ch == 13:
            out += b"\\r"
        else:
            out += b"\\%03o" % ch
    out.append(0x29)
    return bytes(out)


def serialize_value(v):
    if isinstance(v, Ref):
        return b"%d %d R" % (v.num, v.gen)
    if isinstance(v, bool):
        return b"true" if v else b"false"
    if v is None:
        return b"null"
    if isinstance(v, int):
        return b"%d" % v
    if isinstance(v, float):
        return b"%r" % v
    if isinstance(v, bytes):
        return serialize_string(v)
    if isinstance(v, list):
        return b"[" + b" ".join(serialize_value(x) for x in v) + b"]"
    if isinstance(v, dict):
        parts = []
        for k in sorted(v.keys()):
            parts.append(b"/" + k + b" " + serialize_value(v[k]))
        return b"<< " + b" ".join(parts) + b" >>"
    raise PdfParseError(f"cannot serialize {type(v)}")


class PdfBuilder:
    def __init__(self, source_objects):
        self.source_objects = source_objects
        self.objects = {}       # new object number -> structure (or None placeholder)
        self.obj_map = {}       # (old_num, old_gen) -> new number
        self.next_num = 1

    def register(self, structure):
        num = self.next_num
        self.next_num += 1
        self.objects[num] = structure
        return Ref(num, 0)

    def copy_value(self, v):
        if isinstance(v, Ref):
            return self.copy_object(v)
        if isinstance(v, dict):
            return {k: self.copy_value(x) for k, x in v.items()}
        if isinstance(v, list):
            return [self.copy_value(x) for x in v]
        if isinstance(v, StreamObj):
            d = {k: self.copy_value(x) for k, x in v.dict.items()}
            return StreamObj(d, v.raw)
        return v

    def copy_object(self, ref):
        key = (ref.num, ref.gen)
        if key in self.obj_map:
            return Ref(self.obj_map[key], 0)
        src = self.source_objects.get(ref.num)
        if src is None or src[1] is None:
            raise PdfParseError(f"missing object {ref.num}")
        num = self.next_num
        self.next_num += 1
        self.obj_map[key] = num
        copied = self.copy_value(src[1])
        self.objects[num] = copied
        return Ref(num, 0)


# Helvetica glyph widths (units per 1000), ASCII 32..126
HELVETICA_WIDTHS = [
    278, 278, 355, 556, 556, 889, 667, 191, 333, 333, 389, 584, 278, 333, 278, 278,
    556, 556, 556, 556, 556, 556, 556, 556, 556, 556, 278, 278, 584, 584, 584, 556,
    1015, 667, 667, 722, 722, 667, 611, 778, 722, 278, 500, 667, 556, 833, 722, 778,
    667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611, 278, 278, 278, 469, 556,
    333, 556, 556, 500, 556, 556, 278, 556, 556, 222, 222, 500, 222, 833, 556, 556,
    556, 556, 333, 500, 278, 556, 500, 722, 500, 500, 500, 334, 260, 334, 584,
]


def text_width(s, size):
    w = 0
    for ch in s:
        o = ord(ch)
        w += HELVETICA_WIDTHS[o - 32] if 32 <= o <= 126 else 556
    return w * size / 1000.0


def extract_simple_text(data):
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        while i < n and data[i] in b" \t\r\n\f\0":
            i += 1
        if i >= n:
            break
        ch = data[i]
        if data[i:i + 2] == b"BI":  # inline image begin
            j = data.find(b"ID", i + 2)
            if j == -1:
                break
            k = j + 2
            while k < n and data[k] in b" \t\r\n\f\0":
                k += 1
            e = data.find(b"EI", k)
            if e == -1:
                break
            i = e + 2
            continue
        if ch == 0x28:
            s, i2 = parse_literal_string(data, i)
            out += s + b" "
            i = i2
            continue
        if data[i:i + 2] == b"<<":
            i += 2
            continue
        if ch == 0x3C:
            try:
                s, i2 = parse_hex_string(data, i)
            except PdfParseError:
                i += 1
                continue
            out += s + b" "
            i = i2
            continue
        if ch == 0x5B:
            try:
                arr, i2 = parse_array(data, i)
            except PdfParseError:
                i += 1
                continue
            for item in arr:
                if isinstance(item, bytes):
                    out += item + b" "
            i = i2
            continue
        i += 1
    return bytes(out)


def extract_text_from_page(page, objects):
    streams = []

    def add(v):
        if isinstance(v, Ref):
            obj = objects.get(v.num)
            if obj and isinstance(obj[1], StreamObj):
                streams.append(obj[1])
        elif isinstance(v, list):
            for x in v:
                add(x)

    add(page.get(b"Contents"))
    parts = []
    for s in streams:
        try:
            dec = decode_stream(s.dict, s.raw)
        except PdfParseError:
            continue
        parts.append(extract_simple_text(dec))
    return b"\n".join(parts)


if __name__ == "__main__":
    import sys
    from collections import Counter

    path = sys.argv[1] if len(sys.argv) > 1 else "report.pdf"
    try:
        data = open(path, "rb").read()
    except OSError as exc:
        print("error:", exc)
        sys.exit(1)
    print(f"File: {path}  ({len(data)} bytes)")
    m = re.match(rb"%PDF-(\d+\.\d+)", data[:16])
    print("PDF version:", m.group(1).decode() if m else "unknown")
    try:
        entries, trailer, objects = load_pdf(data)
    except PdfParseError as exc:
        print("PARSE FAILED:", exc)
        sys.exit(1)
    print("Xref entries:", len(entries))
    print("Encrypted:", b"Encrypt" in trailer)
    root_ref = trailer.get(b"Root")
    print("Root:", root_ref)
    count = 0
    if isinstance(root_ref, Ref):
        root = objects.get(root_ref.num)
        if root and isinstance(root[1], dict):
            pages_ref = root[1].get(b"Pages")

            def walk(node_ref):
                global count
                node = objects.get(node_ref.num)
                if not node or not isinstance(node[1], dict):
                    return
                d = node[1]
                if d.get(b"Type") == b"Page":
                    count += 1
                elif d.get(b"Kids") is not None:
                    for kid in d[b"Kids"]:
                        if isinstance(kid, Ref):
                            walk(kid)

            if isinstance(pages_ref, Ref):
                walk(pages_ref)
    print("Pages:", count)
    types = Counter()
    filters = Counter()
    streams = 0
    for num, (gen, val) in objects.items():
        if isinstance(val, StreamObj):
            streams += 1
            f = val.dict.get(b"Filter")
            if isinstance(f, bytes):
                filters[f.decode()] += 1
            elif isinstance(f, list):
                for x in f:
                    if isinstance(x, bytes):
                        filters[x.decode()] += 1
            t = val.dict.get(b"Type")
            if isinstance(t, bytes):
                types[t.decode()] += 1
        elif isinstance(val, dict):
            t = val.get(b"Type")
            if isinstance(t, bytes):
                types[t.decode()] += 1
    print("Stream objects:", streams)
    print("Filters:", dict(filters))
    print("Types:", dict(types))
